// en.yaml rule en.fixedPhrases def fixedFound
export function fixedFound(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  start: number,
  end: number,
  alternatives: readonly string[],
  recase: boolean,
): RawFinding | null {
  if (hasUserOrCasedWord(ctx, m[0])) return null;
  const typed = ctx.text.slice(start, end);
  const cased = alternatives.map((alt) => (recase ? caseLike(typed, alt) : alt));
  return {
    ruleId: frame.ruleId,
    messageKey: frame.messageKey,
    range: { start, end },
    alternatives: cased,
    ...(cased.length > 1 ? { requiresChoice: true as const } : {}),
    context: {
      start: Math.max(0, m.index - 32),
      end: Math.min(ctx.text.length, m.index + m[0].length + 16),
    },
  };
}

// en.yaml rule en.fixedPhrases def fixedTarget
export function fixedTarget(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  alternatives: readonly string[],
) {
  const range = group(m, "target");
  return fixedFound(ctx, frame, m, range[0], range[1], alternatives, true);
}

// en.yaml rule en.fixedPhrases def fixedSwap
export function fixedSwap(
  ctx: DetectContext,
  frame: FrameRef,
  m: RegExpExecArray,
  replacement: string | null,
  recase: boolean,
) {
  const range = group(m, "target");
  return replacement ? fixedFound(ctx, frame, m, range[0], range[1], [replacement], recase) : null;
}

// en.yaml rule en.fixedPhrases def fixedTyped
export function fixedTyped(ctx: DetectContext, m: RegExpExecArray) {
  const range = group(m, "target");
  return ctx.text.slice(range[0], range[1]);
}

// en.yaml rule en.fixedPhrases def fixedClauseStart
export function fixedClauseStart(ctx: DetectContext, index: number) {
  return /(?:^|[.!?;:\n])[ \t "“'‘(]*$/.test(enBefore(ctx, index, 96));
}

// en.yaml rule en.fixedPhrases def FIXED_CLOSED_CLASS
export const FIXED_CLOSED_CLASS =
  /^(?:if|in|on|at|to|for|with|by|of|off|out|up|down|over|than|and|or|but|so|as|when|because|since|after|before|until|now|then|again|lately|here|there|yet|still|too|very|it|this|that)$/i;

// en.yaml rule en.fixedPhrases def fixedNounLike
export function fixedNounLike(word: string, unknownLong: boolean) {
  if (!(word && !FIXED_CLOSED_CLASS.test(word))) return false;
  const info = englishWordInfo(word.toLowerCase());
  return info ? info.noun || info.plural : word.length > 6 && (unknownLong || /s$/i.test(word));
}

// en.yaml rule en.fixedPhrases def FIXED_NOUN_DOSE_NEXT
export const FIXED_NOUN_DOSE_NEXT =
  /^(?:of|is|was|are|were|has|had|have|should|would|will|can|could|may|might|must|per|for|and|or|to|in|on|at|level|levels|amount|size|range|form)$/i;

// en.yaml rule en.fixedPhrases def FIXED_PRONOUN_NEXT
export const FIXED_PRONOUN_NEXT = /^(?:it|he|she|this|that|they|we|you|i)$/i;

// en.yaml rule en.fixedPhrases def FIXED_WORSE
export const FIXED_WORSE = new WeakSet<RawFinding>();

// en.yaml rule en.fixedPhrases def FIXED_HELD
export const FIXED_HELD = new WeakSet<RawFinding>();

// en.yaml rule en.fixedPhrases def fixedWorse
export function fixedWorse(ctx: DetectContext, frame: FrameRef, m: RegExpExecArray, word: string) {
  const range = group(m, "target");
  const result = fixedFound(ctx, frame, m, range[0], range[1], [word], true);
  return remember(
    FIXED_WORSE,
    result ??
      remember(FIXED_HELD, {
        ruleId: frame.ruleId,
        messageKey: frame.messageKey,
        range: { start: range[0], end: range[1] },
        alternatives: [],
      }),
  );
}

// en.yaml rule en.fixedPhrases def FIXED_SITUATION
export const FIXED_SITUATION =
  /(?:\bmuch|\b(?:it|this|that|which)(?:['’]s|[ \t ]+(?:is|was|were|be|been|will[ \t ]+be))[ \t ]+(?:(?:a|such[ \t ]+a|quite[ \t ]+a|a[ \t ]+real|a[ \t ]+total|a[ \t ]+complete)[ \t ]+)?)[ \t ]*$/i;

// en.yaml rule en.fixedPhrases def FIXED_NONSENSE_CUE
export const FIXED_NONSENSE_CUE =
  /(?:\b(?:complete|total|utter|absolute|pure|such|dogs|is|was|its|thats|what|bloody|just)|['’]s)[ \t ]+$/i;

// en.yaml rule en.fixedPhrases def FIXED_TO_FAR_NEXT
export const FIXED_TO_FAR_NEXT =
  /^(?:with|for|on|in|this|and|but|when|because|like|away|off|out|flung)$/i;

// en.yaml rule en.fixedPhrases def FIXED_SETTING_VERB
export const FIXED_SETTING_VERB =
  /\b(?:set|sets|setting|change|changes|changed|changing|switch|switched|resize|resized|scale|scaled|convert|converted|from|increase|increased|reduce|reduced|default|defaults|move|moved|grow|grows|grew|shrink|shrank)\b[^.!?;:\n]*$/i;

// en.yaml rule en.sentenceFrames def STYLE2_CLOSED
export const STYLE2_CLOSED = new Set([
  ...STYLE2_DET,
  ...STYLE2_PRONOUNS,
  ...STYLE2_AUX,
  ...STYLE2_PREPOSITIONS,
  ...STYLE2_OTHER_CLOSED,
]);

// en.yaml rule en.sentenceFrames def style2Modifiable
export function style2Modifiable(word: string) {
  const lower = word.toLowerCase();
  if (STYLE2_CLOSED.has(lower)) return false;
  const entry = englishWordInfo(lower);
  return entry ? entry.noun || entry.plural || entry.adjective : /^[a-z]{3,}$/i.test(word);
}

// en.yaml rule en.sentenceFrames def style2OpensClause
export function style2OpensClause(ctx: DetectContext, index: number, also?: RegExp) {
  const before = ctx.text.slice(Math.max(0, index - 48), index);
  return /(?:^|[.!?;:(\n"“][ \t ]*)$/.test(before) || (also?.test(before) ?? false);
}

// en.yaml rule en.sentenceFrames def style2CasedFinding
export function style2CasedFinding(
  ctx: DetectContext,
  range: readonly [number, number],
  ruleId: RawFinding["ruleId"],
  messageKey: RawFinding["messageKey"],
  fix: typeof style2Hyphen,
  evidence: readonly [number, number],
): RawFinding | null {
  if (hasUserOrCasedWord(ctx, ctx.text.slice(evidence[0], evidence[1]))) return null;
  const typed = ctx.source.slice(range[0], range[1]);
  const fixed = fix(typed);
  if (!(fixed !== typed)) return null;
  return finding(ruleId, messageKey, range[0], range[1], [fixed], {
    context: {
      start: Math.max(0, evidence[0] - 48),
      end: Math.min(ctx.text.length, evidence[1] + 16),
    },
  });
}

// en.yaml rule en.sentenceFrames def style2Cased
export function style2Cased(replacement: string) {
  return (typed: string) => applyWordCase(replacement, detectWordCase(typed));
}

// en.yaml rule en.sentenceFrames def style2Hyphen
export function style2Hyphen(typed: string) {
  return typed.replace(/[ \t ]+/, "-");
}

// en.yaml rule en.sentenceFrames def style2Join
export function style2Join(typed: string) {
  return typed.replace(/[ \t ]+/, "");
}

// en.yaml rule en.sentenceFrames def style2CanonicalName
export function style2CanonicalName(
  m: RegExpExecArray,
  ctx: DetectContext,
  frame: FrameRef,
  name: string,
) {
  const range = group(m, "target");
  const typed = m.groups!.target;
  if (typed.split(/[^\p{L}]+/u).some((word) => ctx.dictionary.has(word.toLowerCase()))) return null;
  if (!(typed !== name)) return null;
  return finding(frame.ruleId, frame.messageKey, range[0], range[1], [name], {
    context: { start: Math.max(0, range[0] - 48), end: Math.min(ctx.text.length, range[1] + 16) },
  });
}

// en.yaml rule en.sentenceFrames def style2Previous
export function style2Previous(ctx: DetectContext, index: number) {
  return (
    /(?:(\p{L}+)[ \t ]{1,8})?(\p{L}+)[ \t ]{1,8}$/u
      .exec(ctx.text.slice(Math.max(0, index - 64), index))
      ?.slice(1) ?? []
  );
}

// en.yaml rule en.sentenceFrames def style2Compound
export function style2Compound(ctx: DetectContext, m: RegExpExecArray, fix: typeof style2Hyphen) {
  const range = group(m, "target");
  return style2CasedFinding(
    ctx,
    range,
    "englishClosedCompounds",
    "review_msg_closed_compound",
    fix,
    range,
  );
}

// en.yaml rule en.sentenceFrames def STYLE2_MAKEUP_LEAD
export const STYLE2_MAKEUP_LEAD =
  /(?<![\p{L}'’])(the|a|my|your|his|her|our|their|this|that)[ \t ]{1,8}(?:(\p{L}+)[ \t ]{1,8})?$/iu;

// en.yaml rule en.sentenceFrames def style2MakeUpLead
export function style2MakeUpLead(ctx: DetectContext, m: RegExpExecArray, lead: RegExpExecArray) {
  const det = lead[1];
  const adj = lead[2];
  const entry = adj ? englishWordInfo(adj) : null;
  return adj
    ? !(STYLE2_CLOSED.has(adj.toLowerCase()) || entry?.plural) &&
        !(entry && !entry.adjective && (entry.noun || entry.verbs.length)) &&
        !(!entry && !/^[a-z]{4,}$/.test(adj))
    : !(/^(?:her|that|this)$/i.test(det) && !style2OpensClause(ctx, m.index - lead[0].length));
}

// en.yaml rule en.sentenceFrames def STYLE2_IT_TIME_LEAD
export const STYLE2_IT_TIME_LEAD =
  /\b(?:if|when|whenever|once|because|since|so|and|but|now|maybe|perhaps|think|thought|guess|believe|suppose|feel|felt|say|said|know|knew|reckon|hope)[ \t ]+$/i;

// en.yaml rule en.sentenceFrames def STYLE2_EXISTENTIAL_LEAD
export const STYLE2_EXISTENTIAL_LEAD =
  /\b(?:if|when|that|which|because|and|but|so|where|whether)[ \t ]+$/i;

// en.yaml rule en.irregularWordForms def lexInfoOf
export const lexInfoOf = memoize(englishWordInfo, 20000);

// en.yaml rule en.irregularWordForms def lexKnownOf
export const lexKnownOf = memoize(
  (w: string) => LEXICAL_FUNCTION_WORDS.has(w) || !!lexInfoOf(w) || enListedNoun(w) !== null,
  20000,
);

// en.yaml rule en.irregularWordForms def lexInfo
export function lexInfo(word: string) {
  return lexInfoOf(word.toLowerCase());
}

// en.yaml rule en.irregularWordForms def lexKnown
export function lexKnown(word: string) {
  return lexKnownOf(word.toLowerCase());
}

// en.yaml rule en.irregularWordForms def lexPlainAt
export function lexPlainAt(ctx: DetectContext, word: string, index: number) {
  return /^[a-z]+$/.test(word) || (/^[A-Z][a-z]*$/.test(word) && lexWordBefore(ctx, index) === "");
}

// en.yaml rule en.irregularWordForms def lexWordBefore
export function lexWordBefore(ctx: DetectContext, index: number) {
  const last = lastNonBlankBefore(ctx.text, index);
  if (!(last >= 0 && !/[.!?;:"“\n]/.test(ctx.text[last]))) return "";
  return (
    /([A-Za-z]+)[ \t ]+$/.exec(ctx.text.slice(Math.max(0, index - 40), index))?.[1] ?? "?"
  ).toLowerCase();
}

// en.yaml rule en.irregularWordForms def lexContext
export function lexContext(ctx: DetectContext, start: number, end: number) {
  return { start: Math.max(0, start - 96), end: Math.min(ctx.text.length, end + 40) };
}

// en.yaml rule en.irregularWordForms def LEXICAL_REGULAR_PASTS
export const LEXICAL_REGULAR_PASTS = new Map(
  EN_VERB_FORMS.flatMap((verb) =>
    [
      `${verb.lemma}ed`,
      verb.lemma.endsWith("e") ? `${verb.lemma}d` : "",
      /[^aeiou][aeiou][b-df-hj-np-tv-z]$/.test(verb.lemma)
        ? `${verb.lemma}${verb.lemma.at(-1)}ed`
        : "",
    ]
      .filter(
        (form) =>
          form &&
          !LEXICAL_VALID_VARIANTS.has(form) &&
          form !== verb.past &&
          form !== verb.participle,
      )
      .map((form) => [form, verb] as const),
  ),
);

// en.yaml rule en.irregularWordForms def LEXICAL_REGULAR_PLURALS
export const LEXICAL_REGULAR_PLURALS = new Map(
  [...LEXICAL_IRREGULAR_NOUNS]
    .map((singular) => [singular, englishNounForms(singular)] as const)
    .flatMap(([singular, forms]) =>
      forms ? [[singular + "s", forms] as const, [singular + "es", forms] as const] : [],
    ),
);

// en.yaml rule en.irregularWordForms def LEXICAL_PARTICIPLE_BEFORE
export const LEXICAL_PARTICIPLE_BEFORE =
  /(?:^|[^\p{L}])(?:have|has|had|having|['’]ve|been|be|being|is|are|was|were|am|get|gets|got|gotten)[ \t ]+(?:(?:not|never|already|just|also|all|now)[ \t ]+)?$/iu;

// en.yaml rule en.irregularWordForms def LEXICAL_VERB_BEFORE
export const LEXICAL_VERB_BEFORE =
  /(?:^|[^\p{L}'’])(?:i|you|he|she|it|we|they|who|and|or|then|also|just|never|already|finally|once|have|has|had|having|['’]ve|['’]d|been|be|being|is|are|was|were|am|get|gets|got|gotten)[ \t ]+$/iu;

// en.yaml rule en.irregularWordForms def lexIrregularFor
export function lexIrregularFor(word: string, before: string): string[] | null {
  const w = word.toLowerCase();
  const verb = LEXICAL_REGULAR_PASTS.get(w);
  return verb ? lexIrregularPast(w, verb, before) : lexIrregularPlural(word, w, before);
}

// en.yaml rule en.irregularWordForms def lexIrregularPast
export function lexIrregularPast(w: string, verb: (typeof EN_VERB_FORMS)[number], before: string) {
  if (!(LEXICAL_VERB_BEFORE.test(before) && !lexKnownOf(w))) return null;
  return [LEXICAL_PARTICIPLE_BEFORE.test(before) ? verb.participle : verb.past];
}

// en.yaml rule en.irregularWordForms def lexIrregularPlural
export function lexIrregularPlural(word: string, w: string, before: string) {
  if (!(w.endsWith("s") && w.length >= 4 && !lexInfoOf(w))) return null;
  if (w === "lifes" && /\bstill[ \t ]+$/i.test(before)) return null;
  const cut = lexPluralCut(w, 0, /^[a-z]/.test(word) ? w.length - 3 : 0);
  return cut >= 0 ? lexTablePlural(w, cut) : lexSpelledPlural(w);
}

// en.yaml rule en.irregularWordForms def lexPluralCut
export function lexPluralCut(w: string, cut: number, last: number): number {
  return cut > last
    ? -1
    : LEXICAL_REGULAR_PLURALS.has(w.slice(cut))
      ? cut
      : lexPluralCut(w, cut + 1, last);
}

// en.yaml rule en.irregularWordForms def lexListed
export function lexListed(w: string, singular: string) {
  return (
    enListedNoun(w) === "singular" ||
    (enListedNoun(w) === "plural" && !enListedWithoutPlural(singular))
  );
}

// en.yaml rule en.irregularWordForms def lexTablePlural
export function lexTablePlural(w: string, cut: number) {
  const forms = LEXICAL_REGULAR_PLURALS.get(w.slice(cut))!;
  const head = w.slice(0, cut);
  const singular = head + forms.singular;
  return lexListed(w, singular) ? null : [head + forms.plural, `${singular}'s`];
}

// en.yaml rule en.irregularWordForms def lexSpelledPlural
export function lexSpelledPlural(w: string) {
  const singular = w.slice(0, -1);
  const plural = w.endsWith("os")
    ? `${w.slice(0, -1)}es`
    : /[^aeiou]ys$/.test(w)
      ? `${w.slice(0, -2)}ies`
      : w.endsWith("fs")
        ? `${w.slice(0, -2)}ves`
        : null;
  const spelled = plural && lexInfoOf(plural);
  if (!(spelled && !(spelled.verbs.length > 0 && !spelled.noun))) return null;
  if (!(lexKnownOf(singular) && !lexListed(w, singular))) return null;
  return [plural, `${singular}'s`];
}

// en.yaml rule en.irregularWordForms def lexShortOk
export function lexShortOk(word: string) {
  return word.length > 2 || LEXICAL_SHORT_WORDS.has(word.toLowerCase());
}

// en.yaml rule en.irregularWordForms def lexSplitGlued
export function lexSplitGlued(word: string) {
  const w = word.toLowerCase();
  if (!(w.length >= 6)) return null;
  const cut = lexGluedCut(w, word === w ? LEXICAL_GLUED : LEXICAL_CAPITAL_GLUED, 2);
  if (!(cut >= 0)) return null;
  return `${word.slice(0, cut)} ${w.slice(cut)}`;
}

// en.yaml rule en.irregularWordForms def lexGluedCut
export function lexGluedCut(w: string, heads: ReadonlySet<string>, cut: number): number {
  return cut > 6 || cut > w.length - 3
    ? -1
    : heads.has(w.slice(0, cut)) && lexInfo(w.slice(cut))
      ? cut
      : lexGluedCut(w, heads, cut + 1);
}

// en.yaml rule en.irregularWordForms def lexBoundaryFix
export function lexBoundaryFix(first: string, second: string) {
  const both = !lexKnown(first) && !lexKnown(second);
  const fixes = [
    [first.slice(0, -1), first.slice(-1) + second],
    [first + second[0], second.slice(1)],
  ]
    .filter(
      ([a, b]) =>
        a.length &&
        b.length &&
        lexShortOk(a) &&
        lexShortOk(b) &&
        lexKnown(a) &&
        lexKnown(b) &&
        (both ||
          (Math.min(first.length, second.length) < 3 &&
            (LEXICAL_GLUED.has(a.toLowerCase()) || LEXICAL_GLUED.has(b)))),
    )
    .map(([a, b]) => `${a} ${b}`);
  return !fixes.length &&
    second.length > 2 &&
    lexKnown(first) &&
    !lexKnown(second) &&
    lexInfo(first + second)
    ? [first + second]
    : fixes;
}

// en.yaml rule en.irregularWordForms def LEXICAL_LAST
export const LEXICAL_LAST = new Map([
  [0, { text: "", end: -1, index: 0, word: "", unknown: false }],
]);

// en.yaml rule en.irregularWordForms def lexRemember
export function lexRemember(
  text: string,
  end: number,
  index: number,
  word: string,
  unknown: boolean,
) {
  return LEXICAL_LAST.set(1, LEXICAL_LAST.get(0)!)
    .set(0, { text, end, index, word, unknown })
    .get(1)!;
}

// en.yaml rule en.irregularWordForms def lexWordBeforeSpace
export function lexWordBeforeSpace(
  text: string,
  index: number,
  prior: { text: string; end: number; index: number; word: string; unknown: boolean },
) {
  if (!(text.charCodeAt(index - 1) === 32)) return null;
  return prior.text === text && prior.end === index - 1
    ? { index: prior.index, word: prior.word, unknown: prior.unknown }
    : lexWordAt(text, skipBackWhile(text, index - 1, /[A-Za-z]/), index - 1);
}

// en.yaml rule en.irregularWordForms def lexWordAt
export function lexWordAt(text: string, start: number, end: number) {
  if (!(start !== end && !/[\p{L}\p{M}\p{N}_'’@/#\\.-]/u.test(text[start - 1] ?? ""))) return null;
  const word = text.slice(start, end);
  return { index: start, word, unknown: !lexKnown(word) };
}

// en.yaml rule en.irregularWordForms def lexSpaceFinding
export function lexSpaceFinding(
  ctx: DetectContext,
  index: number,
  word: string,
  w: string,
  unknown: boolean,
  owned: boolean,
  neighbour: ReturnType<typeof lexWordBeforeSpace> | undefined,
  prior: { text: string; end: number; index: number; word: string; unknown: boolean },
): RawFinding | null {
  const end = index + word.length;
  const split =
    unknown && owned && !/[~*^$=\\/]/.test(ctx.text[index - 1] ?? "") && lexSplitGlued(word);
  return split
    ? finding("englishAlotCorrection", "review_msg_split_words", index, end, [split], {
        bulkBlock: "context-dependent",
        context: lexContext(ctx, index, end),
      })
    : lexBoundaryFinding(
        ctx,
        end,
        word,
        w,
        neighbour === undefined ? lexWordBeforeSpace(ctx.scanText, index, prior) : neighbour,
      );
}

// en.yaml rule en.irregularWordForms def lexBoundaryFinding
export function lexBoundaryFinding(
  ctx: DetectContext,
  end: number,
  word: string,
  w: string,
  prev: ReturnType<typeof lexWordBeforeSpace>,
): RawFinding | null {
  if (!(prev && prev.index >= ctx.from && prev.index < ctx.to)) return null;
  if (!(prev.word.length >= 2 && word.length >= 2)) return null;
  if (!(lexPlainAt(ctx, prev.word, prev.index) && !/^[A-Z]/.test(word))) return null;
  if (ctx.dictionary.has(prev.word.toLowerCase())) return null;
  if (LEXICAL_LATIN_PAIRS.has(`${prev.word.toLowerCase()} ${w}`)) return null;
  const fixes = lexBoundaryFix(prev.word, word);
  if (!(fixes.length > 0)) return null;
  return finding("englishAlotCorrection", "review_msg_word_boundary", prev.index, end, fixes, {
    ...(fixes.length > 1 ? { requiresChoice: true as const } : {}),
    bulkBlock: "context-dependent",
    context: lexContext(ctx, prev.index, end),
  });
}

// en.yaml rule en.possessiveNouns def lexOwnerSingular
export function lexOwnerSingular(owner: string) {
  if (
    POSSESSIVE_ATTRIBUTIVE.has(owner) ||
    (/(?:ics|ings|ss|us|is)$/.test(owner) && owner !== "musics")
  )
    return null;
  const read = lexInfo(owner);
  if (!((read?.plural && read.noun) || enListedNoun(owner) === "plural")) return null;
  const stems = owner.endsWith("ies")
    ? [`${owner.slice(0, -3)}y`, owner.slice(0, -1)]
    : owner.endsWith("es")
      ? [owner.slice(0, -1), owner.slice(0, -2)]
      : [owner.slice(0, -1)];
  return stems.find((stem) => lexInfo(stem)?.noun || enListedNoun(stem) === "singular") ?? null;
}

// en.yaml rule en.possessiveNouns def lexNounInfo
export function lexNounInfo(word: string) {
  const read = lexInfo(word);
  const listed = read ? null : enListedNoun(word);
  return read
    ? read.noun && !read.adverb
      ? { info: read, plural: read.plural }
      : null
    : listed
      ? { info: null, plural: listed === "plural" }
      : null;
}

// en.yaml rule en.compoundForms def compoundInfo
export function compoundInfo(word: string | undefined) {
  return word ? englishWordInfo(word.toLowerCase()) : null;
}

// en.yaml rule en.compoundForms def compoundNextWord
export function compoundNextWord(ctx: DetectContext, end: number) {
  return (
    /^[ \t\u00a0]{1,8}(["“]?[\p{L}\p{N}][\p{L}\p{N}'’-]*)/u.exec(
      ctx.text.slice(end, end + 48),
    )?.[1] ?? ""
  );
}

// en.yaml rule en.compoundForms def COMPOUND_OBJECT
export const COMPOUND_OBJECT =
  /^(?:the|a|an|this|that|these|those|my|your|his|her|its|our|their|me|him|us|them|it|you|some|any|every|each|all|no|one|two|three|other|another|more|less)$/i;

// en.yaml rule en.compoundForms def compoundTitled
export function compoundTitled(typed: string) {
  return /\s\p{Lu}/u.test(typed);
}

// en.yaml rule en.compoundForms def compoundHyphenate
export function compoundHyphenate(typed: string) {
  return typed.toLowerCase().split(/\s+/).join("-");
}

// en.yaml rule en.compoundForms def compoundFound
export function compoundFound(
  ctx: DetectContext,
  m: RegExpExecArray,
  alternatives: readonly string[],
  ruleId: RawFinding["ruleId"],
  messageKey: RawFinding["messageKey"],
): RawFinding | null {
  const range = group(m, "target");
  const typed = ctx.text.slice(range[0], range[1]);
  if (!(!hasUserOrCasedWord(ctx, typed) && !compoundTitled(typed))) return null;
  const cased = alternatives.map((alt) => carryCase(typed, alt));
  if (cased.includes(typed)) return null;
  return finding(ruleId, messageKey, range[0], range[1], cased, {
    ...(cased.length > 1 ? { requiresChoice: true as const } : {}),
    context: {
      start: Math.max(0, m.index - 24),
      end: Math.min(ctx.text.length, m.index + m[0].length + 24),
    },
  });
}

// en.yaml rule en.compoundForms def compoundContextual
export function compoundContextual(
  ctx: DetectContext,
  m: RegExpExecArray,
  alternatives: readonly string[],
) {
  return compoundFound(ctx, m, alternatives, "englishContextualCompounds", "review_msg_compounds");
}

// en.yaml rule en.compoundForms def compoundClosed
export function compoundClosed(ctx: DetectContext, m: RegExpExecArray, fix: string) {
  return compoundFound(ctx, m, [fix], "englishClosedCompounds", "review_msg_closed_compound");
}

// en.yaml rule en.compoundForms def COMPOUND_PREMODIFIER
export const COMPOUND_PREMODIFIER =
  /^(?:first|second|third|final|last|next|quick|big|small|major|minor|huge|brief|daily|weekly|monthly|annual|usual|regular|complete|full|proper|good|great|real|official|early|late|short|long|new|old|initial|informal|formal|official|massive|total)$/i;

// en.yaml rule en.compoundForms def COMPOUND_VERB_FORMS
export const COMPOUND_VERB_FORMS = new Map(
  Object.entries(COMPOUND_VERBS).flatMap(([typed, joined]) => compoundVerbForms(typed, joined)),
);

// en.yaml rule en.compoundForms def compoundVerbForms
export function compoundVerbForms(
  typed: string,
  joined: string,
): (readonly [string, readonly [string, string]])[] {
  const parts = typed.split(" ");
  const first = parts[0];
  const second = parts[1];
  const sep = joined.includes("-") ? "-" : "";
  return [
    [typed, [joined, "base"]],
    ...(second === "light"
      ? [[`${first} lighted`, [`${first}${sep}lighted`, "past"]] as const]
      : []),
    ...(["third", "past", "ing"] as const).flatMap((form) =>
      [englishInflect(second, form)].flatMap((inflected) =>
        inflected ? [[`${first} ${inflected}`, [`${first}${sep}${inflected}`, form]] as const] : [],
      ),
    ),
  ];
}

// en.yaml rule en.compoundForms def COMPOUND_TO_OBJECT
export const COMPOUND_TO_OBJECT =
  /^(?:the|a|an|this|that|these|those|my|your|his|her|its|our|their|me|him|us|them|it|you|everything|something|anything|someone|everyone|today|tomorrow|now|again|yet|before|online|myself|yourself|himself|herself|ourselves|themselves)$/i;

// en.yaml rule en.compoundForms def COMPOUND_ARTICLE_MODIFIERS
export const COMPOUND_ARTICLE_MODIFIERS = {
  ...Object.fromEntries(
    [...COMPOUND_HYPHENED_MODIFIERS].map((key) => [key, key.replaceAll(" ", "-")]),
  ),
  "life long": "lifelong",
  "under cover": "undercover",
  "out going": "outgoing",
  "on board": "onboard",
} as Readonly<Record<string, string>>;

// en.yaml rule en.compoundForms def COMPOUND_ARTICLE_NOUNS
export const COMPOUND_ARTICLE_NOUNS = {
  ...Object.fromEntries([...COMPOUND_HYPHENED_NOUNS].map((key) => [key, key.replaceAll(" ", "-")])),
  "home work": "homework",
  "drive way": "driveway",
  "check box": "checkbox",
  "over use": "overuse",
} as Readonly<Record<string, string>>;

// en.yaml rule en.compoundForms def COMPOUND_NOT_NOUN
export const COMPOUND_NOT_NOUN =
  /^(?:of|to|in|on|at|for|from|with|by|and|or|but|is|are|was|were|be|been|has|have|had|will|would|can|could|may|might|must|shall|should|it|this|that|there|then|than|as|so|very|too|now|here|again|also|not|before|after|the|a|an|zone|zones|frame|frames|line|lines|limit|limits|slot|slots|stamp|stamps|span|travel)$/i;

// en.yaml rule en.compoundForms def compoundNounNext
export function compoundNounNext(next: string) {
  if (!(
    !!next &&
    !COMPOUND_NOT_NOUN.test(next) &&
    !COMPOUND_OBJECT.test(next) &&
    !/^\p{N}/u.test(next)
  ))
    return false;
  const entry = compoundInfo(next);
  return /^["“'‘]/u.test(next) || !entry || entry.noun || entry.plural || entry.adjective;
}

// en.yaml rule en.compoundForms def compoundStrictNoun
export function compoundStrictNoun(next: string) {
  if (!(compoundNounNext(next) && /^\p{Ll}/u.test(next))) return false;
  const entry = compoundInfo(next);
  return entry
    ? (entry.noun || entry.plural) && !entry.adverb && !(entry.adjective && !entry.plural)
    : /^[a-z]{6,}$/.test(next);
}

// en.yaml rule en.compoundForms def COMPOUND_PREFIX_WORDS
export const COMPOUND_PREFIX_WORDS = {
  quasi: /^[a-z]{4,}$/,
  mid: /^(?:1[0-9]{3}s?|20[0-9]{2}s?|[0-9]{2}s|twenties|thirties|forties|fifties|sixties|seventies|eighties|nineties|teens|century|season|week|month|year|morning|afternoon|evening|sentence|air|flight|game|range|size|level|term|life|career|race|summer|winter|spring|autumn|fall|january|february|march|april|may|june|july|august|september|october|november|december)$/i,
  pre: /^(?:1[0-9]{3}|20[0-9]{2})s?$/,
  post: /^(?:1[0-9]{3}|20[0-9]{2})s?$/,
  anti: /^\p{Lu}\p{Ll}{3,}$/u,
} as Readonly<Record<string, RegExp>>;

// en.yaml rule en.compoundForms def COMPOUND_NOT_A_HEAD
export const COMPOUND_NOT_A_HEAD =
  /^(?:ago|old|olds|later|earlier|before|after|of|and|or|to|in|on|at|for|from|with|by|per|each|is|was|are|were|left|long|away|late|early|off|behind|ahead|apart|tall|high|wide|deep|thick|away|younger|older|more|less|than|time|times|out|into|over|back|down|up|running|straight|old|this|that|the|a|an|it|he|she|we|they|you|i|there|here|now|then|one|two|three|four|five|six|seven|eight|nine|ten|twenty|thirty|forty|fifty|hundred|thousand)$/i;

// en.yaml rule en.compoundForms def COMPOUND_STEP_KIN
export const COMPOUND_STEP_KIN =
  /^(?:daughters?|sons?|mothers?|fathers?|sisters?|brothers?|child|children|kids?|parents?|dads?|moms?|mums?|siblings?)$/i;

// en.yaml rule en.compoundForms def compoundCountUnit
export function compoundCountUnit(
  ctx: DetectContext,
  m: RegExpExecArray,
  n: string,
  unit: string,
  next: string | undefined,
  before: string,
) {
  const determined = /(?:\b(?:a|an|my|your|his|her|our|their|its)|['’]s)[ \t\u00a0]+$/i.test(
    before,
  );
  if (/^(?:1|one)$/i.test(n) && !determined) return false;
  const article = /\b(?:a|an)[ \t\u00a0]+$/i.test(before);
  if (!(!!next && !COMPOUND_NOT_A_HEAD.test(next) && (compoundNounNext(next) || article)))
    return false;
  if (unit === "step" && COMPOUND_STEP_KIN.test(next ?? "")) return false;
  if (
    /^[0-9,]{4,}$/.test(n) &&
    !/\b(?:a|an|the)[ \t\u00a0]+(?:(?:over|under|nearly|almost|about)[ \t\u00a0]+)?$/i.test(
      ctx.text.slice(Math.max(0, m.index - 16), m.index),
    )
  )
    return false;
  if (/^\p{Lu}/u.test(next ?? "") && compoundInfo(next) === null) return false;
  return true;
}

// en.yaml rule en.compoundForms def compoundKnownNoun
export function compoundKnownNoun(word: string) {
  const known = compoundInfo(word);
  return !!known && (known.noun || known.plural) && !known.adverb;
}

